// ===== ตั้งค่า: แก้ 3 ค่าแรกครั้งเดียว =====
return [{
  json: {
    // อีเมลที่จะรับแจ้งเตือนเมื่อได้ไฟล์ใหม่ — หลายคนคั่นด้วยจุลภาค เช่น 'a@company.com, b@company.com'
    notifyEmail: 'ใส่อีเมลของคุณ@example.com',
    // ID โฟลเดอร์ Google Drive ที่จะเก็บ Playlist (ดูจากลิงก์โฟลเดอร์: drive.google.com/drive/folders/<ID>)
    parentFolderId: 'ใส่_ID_โฟลเดอร์_Google_Drive',
    // ใส่อีเมลผู้ส่ง Playlist ถ้ามี (คั่นด้วย OR) เช่น 'a@company.com OR b@company.com' — เว้นว่าง = ดูทุกอีเมลที่มีไฟล์ Excel แนบ
    fromFilter: '',
    // แบบที่ไม่ได้ส่งมาทุกวัน (latest: true) จะค้นอีเมลย้อนหลังกี่วัน และใช้คำค้นอะไร
    latestDays: 14,
    latestSearch: 'showdc OR "show dc"',
    // Playlist ที่ระบบเติมใบเช็ครูปต้องใช้
    //   pattern = คำในชื่อไฟล์ • latest: true = ถ้าวันนี้ไม่มีฉบับใหม่ ใช้ฉบับล่าสุดที่มี • source: 'line' = ไม่ได้มาทางอีเมล
    // ลำดับมีผล: ไฟล์จะถูกจัดเข้าแบบแรกที่ชื่อตรง
    kinds: [
      { name: 'แยกจอ 40Blue', pattern: 'แยกจอ.*40\\s*Blue' },
      { name: 'แยกจอ 40Red', pattern: 'แยกจอ.*40\\s*Red' },
      { name: 'แยกจอ 80Blue', pattern: 'แยกจอ.*80\\s*Blue' },
      { name: 'แยกจอ 80Red', pattern: 'แยกจอ.*80\\s*Red' },
      { name: 'แยกจอ CITY', pattern: 'แยกจอ.*CITY' },
      { name: 'แยกจอ Spare', pattern: 'แยกจอ.*Spare' },
      { name: 'Show DC', pattern: 'Show[\\s_]*DC', latest: true },
      { name: 'Signature Max', pattern: 'Signature' },
      { name: 'BKJ1', pattern: 'BKJ\\s*1' },
      { name: 'BKJ2', pattern: 'BKJ\\s*2' },
      { name: 'Metro LED', pattern: 'Metro', source: 'line' },
    ],
  },
}];

// คัดไฟล์ Playlist ของ "วันนี้" จากอีเมล (เผื่อ Playlist ส่งมาตั้งแต่เย็นวันก่อน)
// วันที่ของไฟล์ดูจากชื่อไฟล์ก่อน เช่น 2026 10 09, 2026_Oct_09, 9-10-26, 9 Oct 26, 20261009 — ถ้าชื่อไม่มีวันที่ ใช้วันที่ของอีเมล
// แบบที่มี latest: true (เช่น Show DC) ถ้าวันนี้ไม่มีฉบับใหม่ จะใช้ฉบับล่าสุดที่มี
// เก็บทุกไฟล์ของวันนี้ที่เข้าแบบ (บางวันมีมากกว่า 1 ไฟล์ต่อแบบ) และไม่อัปโหลดไฟล์เดิมซ้ำ
const cfg = $('ตั้งค่า').first().json;
const kinds = cfg.kinds.map(k => ({ ...k, re: new RegExp(k.pattern, 'i') }));
const sd = $getWorkflowStaticData('global');
const today = $now.setZone('Asia/Bangkok').toFormat('yyyy-MM-dd');
if (sd.day !== today) { sd.day = today; sd.sent = {}; sd.folderId = ''; }

// ---- อ่านวันที่จากชื่อไฟล์ (กติกาเดียวกับ playlist_system.html + แบบ 20261009) ----
const MON = { jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11 };
const THM = { 'มค': 0, 'กพ': 1, 'มีค': 2, 'เมย': 3, 'พค': 4, 'มิย': 5, 'กค': 6, 'สค': 7, 'กย': 8, 'ตค': 9, 'พย': 10, 'ธค': 11 };
const thisYear = +today.slice(0, 4);
const yy = y => { y = +y; if (y < 100) y += y >= 60 ? 2500 : 2000; if (y > 2400) y -= 543; return y; };
const ymd = (y, m, d) => (m >= 0 && m < 12 && d >= 1 && d <= 31)
  ? `${y}-${String(m + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}` : null;
function nameDate(n) {
  n = String(n).replace(/\.xls[xm]?$/i, '');
  let m = n.match(/(?:^|[^\d])(\d{4})[-_. ](\d{1,2})[-_. ](\d{1,2})(?!\d)/);
  if (m) return ymd(yy(m[1]), +m[2] - 1, +m[3]);
  m = n.match(/(?:^|[^\d])(20\d{2})(\d{2})(\d{2})(?!\d)/);
  if (m) return ymd(+m[1], +m[2] - 1, +m[3]);
  m = n.match(/(?:^|[^\d])(\d{4})[-_. ]?(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*[-_. ]?(\d{1,2})(?!\d)/i);
  if (m) return ymd(yy(m[1]), MON[m[2].toLowerCase()], +m[3]);
  m = n.match(/(?:^|[^\d])(\d{1,2})[-_.](\d{1,2})[-_.](\d{2,4})(?!\d)/);
  if (m) return ymd(yy(m[3]), +m[2] - 1, +m[1]);
  m = n.replace(/\s+/g, '').match(/(\d{1,2})(ม\.?ค\.?|ก\.?พ\.?|มี\.?ค\.?|เม\.?ย\.?|พ\.?ค\.?|มิ\.?ย\.?|ก\.?ค\.?|ส\.?ค\.?|ก\.?ย\.?|ต\.?ค\.?|พ\.?ย\.?|ธ\.?ค\.?)(\d{2,4})?/);
  if (m) return ymd(m[3] ? yy(m[3]) : thisYear, THM[m[2].replace(/\./g, '')], +m[1]);
  m = n.match(/(?:^|[^A-Za-z\d])(\d{1,2})[-_ ]?(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*[-_ ]?(\d{2,4})?(?![A-Za-z])/i);
  if (m) return ymd(m[3] ? yy(m[3]) : thisYear, MON[m[2].toLowerCase()], +m[1]);
  return null;
}
const bkkDay = d => { const t = new Date(d).getTime(); return t ? new Date(t + 7 * 3600e3).toISOString().slice(0, 10) : null; };

const byKind = {};
const others = new Set(); // ไฟล์ Excel ของวันนี้ที่ชื่อไม่ตรงแบบไหนเลย
for (const item of $input.all()) {
  const mailDay = bkkDay(item.json.date);
  const when = new Date(item.json.date || 0).getTime() || 0;
  for (const bin of Object.values(item.binary || {})) {
    const name = (bin.fileName || '').normalize('NFC');
    if (!/\.xlsx?$/i.test(name)) continue;
    const day = nameDate(name) || mailDay;
    if (!day || day > today) continue; // ไฟล์ของวันข้างหน้า รอวันนั้น
    const kind = kinds.find(k => k.re.test(name));
    if (!kind) { if (day === today) others.add(name); continue; }
    if (day !== today && !kind.latest) continue; // ไฟล์ของวันก่อน
    const key = name + '|' + (bin.fileSize || '');
    const list = byKind[kind.name] || (byKind[kind.name] = {});
    if (!list[key]) list[key] = { kind: kind.name, name, key, bin, day, when }; // ไฟล์เดียวกันแนบมาหลายอีเมล = นับครั้งเดียว
  }
}
sd.others = [...others];

const chosen = [];
for (const k of kinds) {
  const list = Object.values(byKind[k.name] || {});
  const todays = list.filter(f => f.day === today);
  if (todays.length) chosen.push(...todays);
  else if (k.latest && list.length) {
    list.sort((a, b) => (a.day < b.day ? -1 : a.day > b.day ? 1 : a.when - b.when));
    chosen.push(list[list.length - 1]); // ฉบับล่าสุดที่มี
  }
}

return chosen
  .filter(f => !sd.sent[f.key]) // อัปโหลดไปแล้ววันนี้
  .map(f => ({
    json: { kind: f.kind, fileName: f.name, key: f.key, fileDay: f.day, folderId: sd.folderId || '' },
    binary: { data: f.bin },
  }));

// จำ ID โฟลเดอร์ของวันนี้ แล้วส่งไฟล์ทั้งหมดต่อไปอัปโหลด
const sd = $getWorkflowStaticData('global');
const folderId = $input.first().json.id;
sd.folderId = folderId;
return $('คัดไฟล์ Playlist').all().map(i => ({
  json: { ...i.json, folderId },
  binary: i.binary,
}));

// บันทึกว่าอัปโหลดไฟล์ไหนแล้ว และเขียนอีเมลสรุปว่าวันนี้ได้ครบหรือยัง
const cfg = $('ตั้งค่า').first().json;
const sd = $getWorkflowStaticData('global');
const picked = $('คัดไฟล์ Playlist').all();
for (const p of picked) sd.sent[p.json.key] = p.json.kind;

const TH = ['ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];
const now = $now.setZone('Asia/Bangkok');
const today = now.toFormat('yyyy-MM-dd');
const thDay = s => `${+s.slice(8, 10)} ${TH[+s.slice(5, 7) - 1]}`; // 'yyyy-MM-dd' → '8 ต.ค.'
const day = `${thDay(today)} ${+today.slice(0, 4) + 543}`;

const mailKinds = cfg.kinds.filter(k => k.source !== 'line').map(k => k.name);
const lineKinds = cfg.kinds.filter(k => k.source === 'line').map(k => k.name);
const counts = {};
for (const k of Object.values(sd.sent)) counts[k] = (counts[k] || 0) + 1;
const haveN = mailKinds.filter(k => counts[k]).length;
const missing = mailKinds.filter(k => !counts[k]);
const multi = mailKinds.filter(k => counts[k] > 1);
const lineTodo = lineKinds.filter(k => !counts[k]);
const link = 'https://drive.google.com/drive/folders/' + sd.folderId;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');

const status = missing.length
  ? `<p>ยังขาด <b>${missing.length}</b> แบบ: ${missing.map(esc).join(', ')}</p><p>ระบบจะเช็กอีเมลทุกชั่วโมงจนถึง 18:00</p>`
  : `<p><b>ครบ ${mailKinds.length} แบบที่มาทางอีเมลแล้ว</b> ดาวน์โหลดทั้งโฟลเดอร์ แล้วลากลงระบบเติมใบเช็ครูปได้เลย</p>`;

const html = `<div style="font-family:Tahoma,sans-serif;font-size:15px;line-height:1.6">
<p>Playlist วันที่ ${esc(day)} — ได้แล้ว <b>${haveN}/${mailKinds.length}</b> แบบ (ที่มาทางอีเมล)</p>
<p>ไฟล์ที่เพิ่งเข้าโฟลเดอร์รอบนี้:</p>
<ul>${picked.map(p => `<li>${esc(p.json.kind)}: ${esc(p.json.fileName)}${p.json.fileDay && p.json.fileDay !== today ? ` <span style="color:#b35a14">(ยังไม่มีฉบับใหม่ — ใช้ฉบับล่าสุด รอบ ${esc(thDay(p.json.fileDay))})</span>` : ''}</li>`).join('')}</ul>
${status}
${lineTodo.length ? `<p style="color:#1d4f91"><b>มาทาง LINE:</b> ${lineTodo.map(esc).join(', ')} — ดาวน์โหลดจาก LINE แล้วใส่ในโฟลเดอร์นี้เอง</p>` : ''}
${multi.length ? `<p style="color:#b35a14"><b>บางแบบมีมากกว่า 1 ไฟล์:</b> ${multi.map(k => `${esc(k)} (${counts[k]} ไฟล์)`).join(', ')} — ตรวจว่าต้องใช้ฉบับไหน หรือใช้ทั้งหมด ก่อนลากลงระบบ</p>` : ''}
${(sd.others || []).length ? `<p style="color:#586274">ไฟล์ Excel อื่นของวันนี้ (ไม่ได้เก็บ เพราะชื่อไม่ตรงแบบที่ใช้):</p><ul style="color:#586274">${sd.others.map(n => `<li>${esc(n)}</li>`).join('')}</ul>` : ''}
<p><a href="${link}">เปิดโฟลเดอร์ Google Drive ของวันนี้</a></p>
</div>`;

return [{
  json: {
    to: cfg.notifyEmail,
    subject: `Playlist ${day}: ${haveN}/${mailKinds.length} แบบ` + (missing.length ? ' (ยังไม่ครบ)' : ' — ครบแล้ว'),
    html,
  },
}];
